import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;

public class TarUtils_formatUnsignedOctalString_TriageGen0Test {









    @Test
    public void testWithOffset() {
        byte[] buffer = new byte[10];
        // Fill with dummy data
        for (int i = 0; i < 10; i++) {
            buffer[i] = (byte) 'X';
        }
        TarUtils.formatUnsignedOctalString(77L, buffer, 2, 4);
        // buffer[0,1] should be 'X'
        // buffer[2,3,4,5] should be '0077'
        // buffer[6,7,8,9] should be 'X'
        byte[] expected = {'X', 'X', '0', '0', '7', '7', 'X', 'X', 'X', 'X'};
        assertArrayEquals(expected, buffer);
    }










}

