import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;

public class TarUtils_formatUnsignedOctalString_TriageGen0Test {













    @Test(expected = IllegalArgumentException.class)
    public void testValueExactlyAtLimitButTriggersError() {
        // The logic: remaining starts at length-1. 
        // If value is 0123 and length is 3, remaining starts at 2.
        // Loop runs for remaining 2, 1, 0.
        // If val is still > 0 after loop, exception.
        byte[] buffer = new byte[3];
        TarUtils.formatUnsignedOctalString(0123L, buffer, 0, 3);
    }






}

package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;

public class TarUtils_formatUnsignedOctalString_TriageGen0Test {















    @Test
    public void testMaxValueForLength() {
        // Max 8-digit octal is 077777777
        long maxVal = 077777777L;
        byte[] buffer = new byte[8];
        TarUtils.formatUnsignedOctalString(maxVal, buffer, 0, 8);
        byte[] expected = "077777777".getBytes(); // Wait, 077777777 is 9 digits.
        // Let's use 77777777 (8 digits)
        long max8 = 077777777L; // This is actually 8 digits in octal
        // Let's be precise:
        long val = 0;
        for(int i=0; i<8; i++) val = (val << 3) | 7; 
        // val is 07777777 (8 digits)

        byte[] buf2 = new byte[8];
        TarUtils.formatUnsignedOctalString(val, buf2, 0, 8);
        byte[] exp2 = "77777777".getBytes();
        assertArrayEquals(exp2, buf2);
    }




}

