package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;

public class TarUtils_formatUnsignedOctalString_TriageGen0Test {



















    @Test(expected = IllegalArgumentException.class)
    public void testZeroLengthBuffer() {
        // length 0 will cause remaining = -1. 
        // If value is 0, buffer[offset + (-1)] will throw ArrayIndexOutOfBounds
        // However, the requirement is to test the logic.
        // If value is 0, remaining becomes -1, it enters if(value==0) block.
        // buffer[offset - 1] is accessed.
        byte[] buffer = new byte[0];
        TarUtils.formatUnsignedOctalString(0L, buffer, 0, 0);
    }
}
